// §10.5 — Human Handoff entry point
// Triggered by: COMPLAINT, HUMAN_HANDOFF_REQUEST, or confidence < 0.6
const ctx = $input.item.json;

// Determine the handoff reason
let reason = 'low_confidence';
if (ctx.intent === 'COMPLAINT')              reason = 'complaint';
if (ctx.intent === 'HUMAN_HANDOFF_REQUEST') reason = 'customer_request';

return [{ json: { ...ctx, handoff_reason: reason } }];

// Build chat snapshot and AI context for the handoff
const history  = $input.all().map(i => i.json);
const ctx      = $('Handoff Entry').item.json;

const chatSnapshot = history.map(msg => ({
  direction:  msg.direction,
  text:       msg.message_text,
  intent:     msg.detected_intent,
  confidence: msg.confidence,
  at:         msg.created_at
}));

const chatText = history
  .slice().reverse()
  .map(m => `[${m.direction.toUpperCase()}] ${m.message_text}`)
  .join('\n');

return [{
  json: {
    ...ctx,
    chat_snapshot: JSON.stringify(chatSnapshot),
    chat_text:     chatText
  }
}];

const aiText   = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text ?? $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
const ctx      = $('Build Chat Snapshot').item.json;
const ticketId = $('Create Support Ticket').item.json.ticket_id;

return [{
  json: {
    ...ctx,
    ticket_id:       ticketId,
    suggested_reply: aiText.trim()
  }
}];

